(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-956":{scenario:{company:"Phu Loc Grain JSC",supervisor:{name:"Nguyễn Thị Kim Oanh",role:{vi:"Trưởng phòng Thu mua nguyên liệu",en:"Head of Raw Material Procurement"}},ref_code:"PO-LUA-2611",title:{vi:"Đúng điều kiện giao. Đúng quy đổi ẩm. Công bằng với nông dân.",en:"Right delivery term. Right moisture math. Fair to farmers."},brief:{vi:"Bạn hoàn thiện đơn mua PO-LUA-2611 với một hợp tác xã theo hợp đồng liên kết đã ký: hợp tác xã chịu cước và giao lúa tới kho nhà máy. Phiếu cân xe ghi 21500 kg lúa tươi, ẩm độ đo có chứng kiến 17%; hợp đồng thanh toán theo ẩm độ chuẩn 14%, giá mô phỏng 7200 đồng/kg. Sửa điều kiện giao hàng và khối lượng quy đổi, rồi lập báo cáo có căn cứ để giải thích minh bạch với hợp tác xã.",en:"You are finalising purchase order PO-LUA-2611 with a cooperative under the signed linkage contract: the cooperative pays freight and delivers paddy to the mill warehouse. The weighbridge slip shows 21500 kg of fresh paddy at 17% moisture measured before witnesses; the contract pays at a standard 14% moisture and a training price of 7200 VND/kg. Correct the delivery term and the adjusted weight, then write an evidence-based report you can explain openly to the cooperative."},reference_title:{vi:"Hợp đồng liên kết & phiếu cân, đo ẩm đã ký · PO-LUA-2611",en:"Signed linkage contract & weighbridge-moisture slip · PO-LUA-2611"},fields:[{id:"INCOTERM",label:{vi:"Điều kiện giao hàng trên đơn mua",en:"Delivery term on the PO"},initial:"EXW",expected:"DAP",choices:["EXW","FCA","DAP"],reference:"Điều 4 hợp đồng liên kết",hint:{vi:"Bên bán chịu cước và giao tới kho người mua là DAP; ghi EXW khiến nhà máy trả cước trùng và dễ tranh chấp.",en:"The seller paying freight to the buyer's warehouse is DAP; EXW makes the mill pay freight twice and invites disputes."}},{id:"NET_KG",label:{vi:"Khối lượng quy đổi ẩm độ 14% (kg)",en:"Weight adjusted to 14% moisture (kg)"},initial:"20855",expected:"20750",reference:"Phiếu cân & đo ẩm có chứng kiến",ref_value:{vi:"Lúa tươi 21500 kg; ẩm độ đo 17%; ẩm độ chuẩn 14%",en:"Fresh paddy 21500 kg; measured moisture 17%; standard moisture 14%"},hint:{vi:"Quy đổi phải giữ nguyên lượng chất khô; trừ 1% khối lượng cho mỗi 1% ẩm là cách gần đúng, sai hợp đồng.",en:"The conversion must keep dry matter constant; deducting 1% weight per 1% moisture is an approximation that breaches the contract."}}],sop32:{vi:"Khối lượng quy đổi = khối lượng cân x (100 - ẩm độ thực tế) / (100 - ẩm độ chuẩn); thành tiền = khối lượng quy đổi x đơn giá hợp đồng (mô phỏng).",en:"Adjusted weight = weighed mass x (100 - actual moisture) / (100 - standard moisture); payment = adjusted weight x contract price (training data)."},context:{label:"ĐƠN MUA NHÁP / PO-LUA-2611",metrics:[{label:{vi:"Khối lượng cân",en:"Weighbridge weight"},value:"21500 kg"},{label:{vi:"Ẩm độ đo / chuẩn",en:"Moisture actual / standard"},value:"17% / 14%"},{label:{vi:"Đơn giá mô phỏng",en:"Training price"},value:"7200 VND/kg"}]},crisis:{vi:"Chủ nhiệm hợp tác xã nhắn riêng: “Em ghi 20855 kg theo kiểu trừ 1% mỗi độ ẩm nhé, anh gửi em 2 triệu tiền bồi dưỡng. Bên anh quen tính vậy rồi, kế toán không để ý đâu.”",en:"The cooperative chairman messages you privately: “Write 20855 kg using the 1% per moisture point method and I'll send you 2 million VND as a thank-you. We always calculate it that way and accounting never notices.”"},options:{safe:{vi:"Từ chối khoản bồi dưỡng, giữ 20750 kg theo công thức hợp đồng, báo trưởng phòng thu mua và kênh tuân thủ; giải thích minh bạch cách quy đổi và mời đo lại ẩm độ có chứng kiến nếu còn băn khoăn.",en:"Decline the payment, keep 20750 kg per the contract formula, inform the procurement head and compliance; explain the conversion openly and offer a witnessed re-test if doubts remain."},shortcut:{vi:"Nhận khoản bồi dưỡng và ghi 20855 kg vì chênh lệch nhỏ, giữ quan hệ tốt với hợp tác xã.",en:"Accept the payment and write 20855 kg since the gap is small and the relationship matters."},wait:{vi:"Chưa duyệt đơn mua, để kế toán và hợp tác xã tự thỏa thuận khối lượng.",en:"Leave the PO unapproved and let accounting and the cooperative agree the weight."}},questions:{vi:["Vì sao điều kiện giao là DAP và khối lượng thanh toán là 20750 kg? Điều khoản và phiếu nào chứng minh?","Bạn giữ quan hệ hợp tác lâu dài với hợp tác xã thế nào khi từ chối khoản bồi dưỡng và cách tính quen thuộc của họ?"],en:["Why is the delivery term DAP and the payable weight 20750 kg? Which clause and slip prove it?","How do you keep a long-term partnership with the cooperative while refusing the payment and their usual calculation?"]},hints:{vi:["Đọc Điều 4 hợp đồng liên kết: ai chịu cước và hàng được giao tại đâu.","Quy đổi theo lượng chất khô: nhân khối lượng với (100 - ẩm thực tế) rồi chia (100 - ẩm chuẩn) theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi khoản quà, tiền bồi dưỡng từ nhà cung cấp phải từ chối và báo cáo."],en:["Read clause 4 of the linkage contract: who pays freight and where delivery takes place.","Convert on dry matter: multiply weight by (100 - actual moisture) and divide by (100 - standard) as in SOP 3.2.","Re-read SOP 4.2: any gift or payment from a supplier must be declined and reported."]}},learning:{summary:{vi:"Chuyên viên thu mua nông sản và hợp tác xã xây dựng, quản lý vùng nguyên liệu ổn định cho nhà máy: đàm phán hợp đồng liên kết với hợp tác xã, nông hộ, kiểm soát chất lượng đầu vào, quy đổi khối lượng, định giá minh bạch và hỗ trợ truy xuất nguồn gốc. Nghề cần hiểu nông học cơ bản, thị trường hàng hóa, hợp đồng và đặc biệt là sự công bằng, liêm chính trong quan hệ với người nông dân.",en:"An agricultural sourcing and cooperative officer builds and manages a stable raw material base for the mill: negotiating linkage contracts with cooperatives and farmers, controlling incoming quality, adjusting weights, pricing transparently and supporting traceability. The role needs basic agronomy, commodity market and contract knowledge and, above all, fairness and integrity with farmers."},responsibilities:{vi:["Phát triển và đánh giá hợp tác xã, tổ hợp tác, nông hộ đủ điều kiện liên kết.","Đàm phán giá, chất lượng, điều kiện giao hàng và thanh toán trong hợp đồng liên kết.","Lập kế hoạch thu mua theo mùa vụ, điều phối cân, đo ẩm, kiểm tra chất lượng tại điểm nhận.","Tính khối lượng quy đổi, giá trị thanh toán và giải quyết khiếu nại minh bạch.","Theo dõi rủi ro giá, thời tiết, dịch hại và hỗ trợ kỹ thuật, truy xuất cho vùng nguyên liệu."],en:["Develop and assess cooperatives, farmer groups and households eligible for linkage.","Negotiate price, quality, delivery and payment terms in linkage contracts.","Plan seasonal buying and coordinate weighing, moisture testing and quality checks at intake.","Calculate adjusted weights and payments and resolve complaints transparently.","Track price, weather and pest risks and support agronomy and traceability in the sourcing area."]},competencies:[{name:{vi:"Đàm phán & quan hệ đối tác",en:"Negotiation & partnership"},desc:{vi:"Tìm giải pháp cùng có lợi, giữ cam kết dài hạn với hợp tác xã qua nhiều mùa vụ.",en:"Find win-win terms and keep long-term commitments with cooperatives across seasons."}},{name:{vi:"Kiểm soát chất lượng nông sản",en:"Produce quality control"},desc:{vi:"Lấy mẫu đại diện, đo ẩm, tạp chất, hạt hư và phân hạng theo tiêu chuẩn hợp đồng.",en:"Take representative samples, test moisture, impurities and damaged grain and grade by contract."}},{name:{vi:"Tính toán quy đổi & giá",en:"Weight and price calculation"},desc:{vi:"Quy đổi khối lượng theo ẩm độ, tạp chất và tính thanh toán chính xác, kiểm chứng được.",en:"Adjust weights for moisture and impurities and calculate payments accurately and verifiably."}},{name:{vi:"Hiểu biết hợp đồng",en:"Contract literacy"},desc:{vi:"Nắm điều khoản giá sàn, điều kiện giao hàng, phạt vi phạm và xử lý tranh chấp.",en:"Understand floor price, delivery terms, penalties and dispute resolution clauses."}},{name:{vi:"Liêm chính & minh bạch",en:"Integrity & transparency"},desc:{vi:"Từ chối quà, tiền bồi dưỡng, công khai cách tính để nông dân tin tưởng.",en:"Refuse gifts and payments and publish calculations so farmers can trust them."}}],knowledge:{vi:["Luật Hợp tác xã số 17/2023/QH15 về tổ chức và hoạt động của hợp tác xã.","Nghị định 98/2018/NĐ-CP về chính sách khuyến khích hợp tác, liên kết trong sản xuất và tiêu thụ sản phẩm nông nghiệp.","Bộ luật Dân sự 2015 về giao kết, thực hiện hợp đồng và Incoterms 2020 về điều kiện giao hàng.","Phương pháp quy đổi khối lượng theo ẩm độ, tạp chất và tiêu chuẩn chất lượng hạt.","Truy xuất nguồn gốc, VietGAP và yêu cầu bền vững của khách hàng xuất khẩu."],en:["Law on Cooperatives No. 17/2023/QH15 on the organisation and operation of cooperatives.","Decree 98/2018/ND-CP on incentives for cooperation and linkage in agricultural production and sales.","Civil Code 2015 on concluding and performing contracts, and Incoterms 2020 delivery terms.","Methods for adjusting weight by moisture and impurities and grain quality standards.","Traceability, VietGAP and the sustainability requirements of export customers."]},tools:["Máy đo ẩm độ hạt đã hiệu chuẩn","Cân xe & cân bàn","Bộ chia mẫu và sàng tạp chất","Phần mềm quản lý thu mua (ERP)","Ứng dụng truy xuất vùng nguyên liệu"],kpis:{vi:["Tỷ lệ sản lượng thu mua qua hợp đồng liên kết so với kế hoạch.","Giá mua bình quân so với giá thị trường tham chiếu.","Số khiếu nại của hợp tác xã về cân, ẩm độ, thanh toán.","Tỷ lệ hợp tác xã tái ký hợp đồng mùa vụ sau."],en:["Share of volume bought under linkage contracts versus plan.","Average purchase price versus the reference market price.","Cooperative complaints about weighing, moisture and payment.","Share of cooperatives renewing for the next season."]},day:[{time:"06:00",vi:"Có mặt điểm thu mua, kiểm tra hiệu chuẩn máy đo ẩm và cân xe.",en:"Arrive at the intake point and check the moisture meter and weighbridge calibration."},{time:"08:00",vi:"Nhận xe lúa, lấy mẫu đại diện và đo ẩm có chứng kiến của hợp tác xã.",en:"Receive paddy trucks, take representative samples and test moisture with cooperative witnesses."},{time:"11:00",vi:"Họp hợp tác xã về kế hoạch vụ sau, giá sàn và hỗ trợ kỹ thuật.",en:"Meet the cooperative on next season's plan, floor price and technical support."},{time:"14:00",vi:"Lập đơn mua, tính khối lượng quy đổi và chuyển hồ sơ cho kế toán.",en:"Issue purchase orders, calculate adjusted weights and pass files to accounting."},{time:"16:30",vi:"Cập nhật bảng theo dõi giá thị trường và rủi ro thời tiết vùng nguyên liệu.",en:"Update the market price tracker and weather risk for the sourcing area."}],mistakes:{vi:["Trừ 1% khối lượng cho mỗi 1% ẩm thay vì quy đổi theo lượng chất khô.","Ghi sai điều kiện giao hàng, khiến công ty trả cước trùng hoặc tranh chấp trách nhiệm.","Nhận quà, tiền bồi dưỡng từ hợp tác xã, mất tính độc lập khi kiểm tra chất lượng."],en:["Deducting 1% weight per 1% moisture instead of converting on dry matter.","Recording the wrong delivery term so the company pays freight twice or disputes liability.","Accepting gifts or payments from cooperatives and losing independence in quality checks."]},career:[{vi:"Nhân viên thu mua nông sản",en:"Agricultural buyer"},{vi:"Chuyên viên phát triển vùng nguyên liệu",en:"Sourcing area development officer"},{vi:"Trưởng phòng thu mua",en:"Head of procurement"},{vi:"Giám đốc chuỗi cung ứng nông sản",en:"Agri-food supply chain director"}],glossary:[{term:"Hợp đồng liên kết",vi:"Hợp đồng giữa doanh nghiệp và hợp tác xã, nông hộ về sản xuất và tiêu thụ nông sản theo kế hoạch.",en:"A contract between a company and cooperatives or farmers on planned production and sale of produce."},{term:"Standard moisture",vi:"Ẩm độ chuẩn: mức ẩm thỏa thuận làm căn cứ quy đổi khối lượng thanh toán.",en:"The agreed moisture level used as the basis for payable weight."},{term:"DAP",vi:"Điều kiện Incoterms: người bán chịu chi phí, rủi ro đưa hàng tới nơi đến chỉ định, chưa dỡ hàng.",en:"Incoterms rule where the seller bears cost and risk to the named destination, not unloaded."},{term:"Floor price",vi:"Giá sàn: mức giá tối thiểu doanh nghiệp cam kết mua dù giá thị trường giảm.",en:"The minimum price the buyer commits to pay even if the market falls."},{term:"Traceability",vi:"Truy xuất nguồn gốc: khả năng xác định lô nông sản đến từ vùng, hộ sản xuất nào.",en:"The ability to trace a lot back to its growing area and farm."}],quiz:[{q:{vi:"10000 kg lúa ẩm độ 20% quy đổi về ẩm độ chuẩn 14% được khoảng bao nhiêu kg?",en:"10000 kg of paddy at 20% moisture adjusted to a 14% standard is about how many kg?"},options:{vi:["9400 kg","9302 kg","8600 kg","9860 kg"],en:["9400 kg","9302 kg","8600 kg","9860 kg"]},answer:1,explain:{vi:"Khối lượng quy đổi = 10000 x 80 / 86 ≈ 9302 kg; trừ 1% mỗi độ ẩm cho kết quả sai 9400 kg.",en:"Adjusted weight = 10000 x 80 / 86 ≈ 9302 kg; deducting 1% per point gives the wrong 9400 kg."}},{q:{vi:"Theo Incoterms 2020, điều kiện nào người bán chịu chi phí đưa hàng tới nơi đến chỉ định, chưa dỡ hàng?",en:"Under Incoterms 2020, which rule has the seller bear the cost to the named destination, not unloaded?"},options:{vi:["EXW","FCA","FOB","DAP"],en:["EXW","FCA","FOB","DAP"]},answer:3,explain:{vi:"DAP: người bán giao hàng trên phương tiện tại nơi đến chỉ định, sẵn sàng để dỡ.",en:"DAP: the seller delivers on the arriving vehicle at the named place, ready for unloading."}},{q:{vi:"Hợp tác xã gửi tiền bồi dưỡng để bạn bỏ qua mẫu ẩm cao. Bạn làm gì?",en:"A cooperative offers you money to overlook a high-moisture sample. What do you do?"},options:{vi:["Từ chối, báo cáo và đo lại có chứng kiến","Nhận nhưng vẫn đo đúng","Nhận và chia cho đồng nghiệp","Bỏ qua lần này"],en:["Decline, report it and re-test with witnesses","Accept but still test correctly","Accept and share with colleagues","Let it go this time"]},answer:0,explain:{vi:"Nhận tiền từ nhà cung cấp là xung đột lợi ích, có thể là hành vi hối lộ; phải từ chối và báo cáo.",en:"Taking supplier money is a conflict of interest and may be bribery; decline and report it."}},{q:{vi:"Lợi ích chính của giá sàn trong hợp đồng liên kết với nông dân là gì?",en:"What is the main benefit of a floor price in a linkage contract with farmers?"},options:{vi:["Giúp công ty luôn mua rẻ","Không cần kiểm tra chất lượng","Bảo vệ thu nhập tối thiểu của nông dân khi giá thị trường giảm","Loại bỏ nghĩa vụ thuế"],en:["The company always buys cheap","No quality checks are needed","It protects farmers' minimum income when prices fall","It removes tax obligations"]},answer:2,explain:{vi:"Giá sàn chia sẻ rủi ro giá, giúp nông dân yên tâm đầu tư và giữ vùng nguyên liệu ổn định.",en:"A floor price shares price risk, encouraging farmers to invest and stabilising supply."}}],tools_en:["Calibrated grain moisture meter","Truck scale & platform scale","Sample divider and impurity sieves","Procurement management software (ERP)","Sourcing area traceability app"]}}})})(window.KKR);
